return $input.all().map((item) => {
  const data = item.json;
  const rawPhone = String(data.phone ?? '').trim();
  const digits = rawPhone.replace(/\D/g, '');

  let phone = '';

  if (rawPhone.startsWith('+')) {
    phone = `+${digits}`;
  } else if (digits.startsWith('00')) {
    phone = `+${digits.slice(2)}`;
  } else if (digits.startsWith('34')) {
    phone = `+${digits}`;
  } else if (/^[6789]\d{8}$/.test(digits)) {
    phone = `+34${digits}`;
  } else if (digits) {
    phone = `+${digits}`;
  }

  const leadKey = String(
    data.lead_key || data.lead_id || ''
  ).trim();

  return {
    json: {
      ...data,
      lead_key: leadKey,
      lead_id: leadKey,
      phone,
      scenario:
        data.scenario || 'BANT-кваліфікація нового ліда',
      is_valid_phone: /^\+[1-9]\d{7,14}$/.test(phone),
    },
  };
});

const root =
  $json.body && typeof $json.body === 'object'
    ? $json.body
    : $json;

const nested =
  root.data && typeof root.data === 'object'
    ? root.data
    : {};

// Динамические переменные, переданные в HAPP при запуске звонка
const dynamic =
  root.dynamic_variables ??
  nested.dynamic_variables ??
  root.dynamicVariables ??
  nested.dynamicVariables ??
  root.conversation_initiation_client_data?.dynamic_variables ??
  nested.conversation_initiation_client_data?.dynamic_variables ??
  {};

// Параметры, полученные от инструмента save_call_report
const report =
  root.params ??
  nested.params ??
  root.report ??
  nested.report ??
  {};

const analysis =
  root.analysis ??
  nested.analysis ??
  {};

const metadata =
  root.metadata ??
  nested.metadata ??
  {};

const text = (value) =>
  value === null || value === undefined
    ? ''
    : String(value).trim();

// Транскрипция может прийти как массив либо уже готовая строка
const rawTranscript =
  root.transcript ??
  nested.transcript ??
  analysis.transcript ??
  '';

const turns = Array.isArray(rawTranscript)
  ? rawTranscript
  : [];

const transcript = Array.isArray(rawTranscript)
  ? turns
      .filter((turn) => text(turn?.message))
      .map((turn) => {
        const role =
          turn.role === 'user'
            ? 'Клієнт'
            : turn.role === 'agent'
              ? 'Агент'
              : text(turn.role);

        return `${role}: ${text(turn.message)}`;
      })
      .join('\n')
  : text(rawTranscript);

const toolCalls = turns.flatMap((turn) =>
  Array.isArray(turn?.tool_calls)
    ? turn.tool_calls
    : []
);

const endCall = toolCalls.find(
  (tool) => tool.tool_name === 'end_call'
);

let endCallParams = endCall?.params_as_json ?? {};

if (typeof endCallParams === 'string') {
  try {
    endCallParams = JSON.parse(endCallParams);
  } catch {
    endCallParams = {};
  }
}

// Важно: ищем lead_id во всех возможных местах payload
const leadId = text(
  dynamic.lead_key ??
  dynamic.lead_id ??
  report.lead_key ??
  report.lead_id ??
  root.lead_key ??
  nested.lead_key
);

const phone = text(
  report.phone ??
  root.phone ??
  nested.phone ??
  dynamic.phone ??
  dynamic.phone_number ??
  dynamic.system__caller_id
);

const rawScore = Number(
  report.ai_score ??
  root.ai_score ??
  nested.ai_score
);

const rawDuration = Number(
  report.duration_seconds ??
  metadata.call_duration_secs ??
  root.duration_seconds ??
  nested.duration_seconds ??
  dynamic.system__call_duration_secs ??
  0
);

return [
  {
    json: {
      lead_id: leadId,

      client_name: text(
        report.client_name ??
        root.client_name ??
        nested.client_name ??
        dynamic.client_name
      ),

      phone,

      company: text(
        report.company ??
        root.company ??
        nested.company ??
        dynamic.company
      ),

      scenario: text(
        report.scenario ??
        root.scenario ??
        nested.scenario ??
        dynamic.scenario
      ),

      budget: text(
        report.budget ??
        dynamic.budget
      ),

      authority: text(
        report.authority ??
        report.decision_maker ??
        dynamic.authority ??
        dynamic.decision_maker
      ),

      need: text(
        report.need ??
        dynamic.need
      ),

      timeline: text(
        report.timeline ??
        dynamic.timeline
      ),

      pain: text(
        report.pain ??
        dynamic.pain
      ),

      decision_maker: text(
        report.decision_maker ??
        report.authority ??
        dynamic.decision_maker ??
        dynamic.authority
      ),

      next_step: text(
        report.next_step ??
        endCallParams.reason
      ),

      result: text(
        report.result
      ),

      summary: text(
        report.summary ??
        analysis.transcript_summary ??
        analysis.summary
      ),

      ai_score: Number.isFinite(rawScore)
        ? Math.max(0, Math.min(100, rawScore))
        : null,

      lead_temperature: text(
        report.lead_temperature
      ),

      human_handoff:
        report.human_handoff === true ||
        text(report.human_handoff).toLowerCase() === 'true',

      duration_seconds: Number.isFinite(rawDuration)
        ? rawDuration
        : 0,

      transcript,

      conversation_id: text(
        root.conversation_id ??
        nested.conversation_id ??
        dynamic.system__conversation_id
      ),

      call_session_id: text(
        root.call_session_id ??
        nested.call_session_id ??
        metadata.call_session_id ??
        dynamic.call_session_id
      ),

      recording_url: text(
        root.recordUrl ??
        nested.recordUrl ??
        root.recording_url ??
        nested.recording_url ??
        metadata.recording_url
      ),

      happ_call_status: text(
        root.status ??
        nested.status ??
        report.call_status
      ),

      happ_call_successful: text(
        analysis.call_successful ??
        root.call_successful ??
        nested.call_successful
      ),

      sentiment: text(
        analysis.sentiment_analysis?.overall_label ??
        analysis.sentiment ??
        root.sentiment ??
        nested.sentiment
      ),

      has_lead_id: Boolean(leadId)
    }
  }
];

const base =
  $('Нормалізація результату дзвінка')
    .first()
    .json;

let ai =
  $json.output ??
  $json.text ??
  $json.response ??
  $json;

if (typeof ai === 'string') {
  const cleaned = ai
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();

  try {
    ai = JSON.parse(cleaned);
  } catch {
    throw new Error(
      `AI повернув невалідний JSON: ${cleaned}`
    );
  }
}

const score = Math.max(
  0,
  Math.min(100, Number(ai.ai_score) || 0)
);

const temperature =
  ai.lead_temperature ||
  (score >= 75
    ? 'Hot'
    : score >= 45
      ? 'Warm'
      : 'Cold');

return [{
  json: {
    ...base,
    ...ai,

    lead_id: base.lead_id,
    client_name: base.client_name,
    phone: base.phone,
    company: base.company,
    scenario: base.scenario,

    ai_score: score,
    lead_temperature: temperature,

    human_handoff:
      ai.human_handoff === true ||
      String(ai.human_handoff).toLowerCase() === 'true',

    duration_seconds: base.duration_seconds,
    transcript: base.transcript,
    conversation_id: base.conversation_id,
    call_session_id: base.call_session_id,
    recording_url: base.recording_url,

    has_lead_id: Boolean(base.lead_id)
  }
}];
